import {
  Body,
  Head as EmailHead,
  Html,
  Preview,
  Link,
  Section,
  Row,
  Column,
  Img,
} from "jsx-email";
import { Fragment } from "react";

import { DefaultFonts } from "@/components/email/font-default";
import { EmailTailwind } from "@/components/email/email-theme";
import type { EmailTheme } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";

export type HeaderWithLogoAndBadgeAlignment = "left" | "center" | "right";

export interface HeaderWithLogoAndBadgeProps {
  theme?: EmailTheme;
  logoSrc?: string;
  logoAlt?: string;
  logoHref?: string;
  badgeLabel?: string;
  message?: string;
  alignment?: HeaderWithLogoAndBadgeAlignment;
  pageBackgroundColor?: string;
  backgroundColor?: string;
  badgeBackgroundColor?: string;
  badgeBorderColor?: string;
  badgeColor?: string;
  badgeTextColor?: string;
}

const fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const responsiveStyles = [
  "@media only screen and (max-width: 599px) {",
  "  .header-badge-stack { display: block !important; width: 100% !important; }",
  "  .header-badge-after { padding-top: 24px !important; }",
  "  .header-badge-before { padding-bottom: 24px !important; }",
  "  .header-badge-mobile-table { float: none !important; margin-left: 0 !important; }",
  "  .header-badge-mobile-logo { text-align: left !important; }",
  "}",
].join("\n");

const defaults = {
  backgroundColor: "#fffffe",
  badgeBackgroundColor: "#eff6ff",
  badgeBorderColor: "#dbeafe",
  badgeColor: "#2563eb",
  badgeLabel: "FREE SHIPPING",
  badgeTextColor: "#4b5563",
  logoAlt: "Maizzle",
  logoHref: "https://example.com",
  logoSrc: emailAsset("maizzle-insignia.png"),
  message: "On orders over $65",
  pageBackgroundColor: "#f1f5f9",
};

type SectionProps = Omit<HeaderWithLogoAndBadgeProps, "theme">;

type ResolvedProps = typeof defaults & SectionProps;

const Logo = ({ props }: { props: ResolvedProps }) => (
  <Link href={props.logoHref}>
    <Img
      alt={props.logoAlt}
      src={props.logoSrc}
      style={{ maxWidth: "100%", verticalAlign: "middle" }}
      width={55}
    />
  </Link>
);

const Badge = ({
  align,
  props,
}: {
  align?: "center" | "right";
  props: ResolvedProps;
}) => {
  let tableStyle:
    | {
        marginLeft: string;
        marginRight?: string;
      }
    | undefined;
  if (align === "center") {
    tableStyle = { marginLeft: "auto", marginRight: "auto" };
  } else if (align === "right") {
    tableStyle = { marginLeft: "auto" };
  }
  return (
    <Section
      align={align}
      className={align === "center" ? undefined : "header-badge-mobile-table"}
      style={tableStyle}
    >
      <Fragment>
        <Row>
          <Column
            style={{
              backgroundColor: props.badgeBackgroundColor,
              borderRadius: "9999px",
              color: props.badgeColor,
              fontFamily,
              fontSize: "12px",
              fontWeight: 500,
              lineHeight: "18px",
              padding: "4px",
              paddingRight: "8px",
            }}
          >
            <span
              style={{
                backgroundColor: props.backgroundColor,
                border: `1px solid ${props.badgeBorderColor}`,
                borderRadius: "9999px",
                boxShadow: "0 1px 2px 0 rgba(0,0,0,0.05)",
                color: props.badgeTextColor,
                display: "inline-block",
                fontFamily,
                fontSize: "12px",
                fontWeight: 500,
                lineHeight: "16px",
                padding: "2px 8px",
              }}
            >
              {props.badgeLabel}
            </span>{" "}
            <span>{props.message}</span>
          </Column>
        </Row>
      </Fragment>
    </Section>
  );
};

export const HeaderWithLogoAndBadgeSection = (props: SectionProps) => {
  const alignment = props.alignment ?? "left";
  const resolved = { ...defaults, ...props } as ResolvedProps;
  let content;
  if (alignment === "center") {
    content = (
      <Section width="100%">
        <Fragment>
          <Row>
            <Column>
              <Section style={{ textAlign: "center" }}>
                <Logo props={resolved} />
              </Section>
              <Section style={{ lineHeight: "24px" }}>&zwj;</Section>
              <Badge align="center" props={resolved} />
            </Column>
          </Row>
        </Fragment>
      </Section>
    );
  } else if (alignment === "right") {
    content = (
      <Section width="100%">
        <Fragment>
          <Row>
            <Column className="header-badge-stack header-badge-before">
              <Badge props={resolved} />
            </Column>
            <Column
              className="header-badge-stack header-badge-mobile-logo"
              style={{ textAlign: "right", width: "55px" }}
            >
              <Logo props={resolved} />
            </Column>
          </Row>
        </Fragment>
      </Section>
    );
  } else {
    content = (
      <Section width="100%">
        <Fragment>
          <Row>
            <Column className="header-badge-stack" style={{ width: "55px" }}>
              <Logo props={resolved} />
            </Column>
            <Column className="header-badge-stack header-badge-after">
              <Badge align="right" props={resolved} />
            </Column>
          </Row>
        </Fragment>
      </Section>
    );
  }
  return (
    <Section
      style={{ backgroundColor: resolved.pageBackgroundColor }}
      width="100%"
    >
      <Fragment>
        <Row>
          <Column>&zwj;</Column>
          <Column style={{ maxWidth: "100%", width: "600px" }}>
            <Section width="100%">
              <Fragment>
                <Row>
                  <Column
                    style={{
                      backgroundColor: resolved.backgroundColor,
                      padding: "24px",
                    }}
                  >
                    {content}
                  </Column>
                </Row>
              </Fragment>
            </Section>
          </Column>
          <Column>&zwj;</Column>
        </Row>
      </Fragment>
    </Section>
  );
};

export const HeaderWithLogoAndBadge = ({
  alignment = "left",
  pageBackgroundColor = "#f1f5f9",
  theme = defaultTheme,
  ...props
}: HeaderWithLogoAndBadgeProps) => (
  <Html>
    <EmailHead>
      <DefaultFonts />
      <style dangerouslySetInnerHTML={{ __html: responsiveStyles }} />
    </EmailHead>
    <Preview>FREE SHIPPING On orders over $65</Preview>
    <EmailTailwind theme={theme}>
      <Body
        style={{ backgroundColor: pageBackgroundColor, fontFamily }}
        className="m-0"
      >
        <HeaderWithLogoAndBadgeSection
          {...props}
          alignment={alignment}
          pageBackgroundColor={pageBackgroundColor}
        />
      </Body>
    </EmailTailwind>
  </Html>
);

HeaderWithLogoAndBadge.PreviewProps = {
  alignment: "left",
  theme: defaultTheme,
} satisfies HeaderWithLogoAndBadgeProps;

const ASSET_ORIGIN = "https://www.emailcn.run";

const palettes = [
  ["4F46E5", "FFFFFF"],
  ["0F766E", "FFFFFF"],
  ["C2410C", "FFFFFF"],
  ["7E22CE", "FFFFFF"],
  ["0369A1", "FFFFFF"],
  ["BE123C", "FFFFFF"],
] as const;

const hashString = (value: string) => {
  let hash = 7;

  for (const character of value) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 2_147_483_647;
  }

  return hash;
};

const getDimensions = (path: string) => {
  if (/(?:avatar|user|headshot)/i.test(path)) {
    return [160, 160] as const;
  }
  if (/(?:logo|insignia)/i.test(path)) {
    return [320, 96] as const;
  }
  if (/(?:badge-app|badge-google)/i.test(path)) {
    return [260, 80] as const;
  }
  if (/(?:icon|btc|eth)/i.test(path)) {
    return [64, 64] as const;
  }
  if (/(?:portrait|member|team)/i.test(path)) {
    return [600, 800] as const;
  }
  if (/(?:square|product|shopping-cart)/i.test(path)) {
    return [700, 700] as const;
  }
  if (/(?:hero|footer|background|bg-|overlay|full-width)/i.test(path)) {
    return [1200, 700] as const;
  }
  if (/(?:strip|landscape|bento|category-preview)/i.test(path)) {
    return [800, 520] as const;
  }

  return [800, 600] as const;
};

const getLabel = (path: string) => {
  const fileName = path.split("/").at(-1) ?? "emailcn";

  return fileName
    .replace(/\.[^.]+$/, "")
    .replace(/^(?:logo|badge|icon)-/, "")
    .replaceAll("-", " ")
    .replaceAll(/\b\w/g, (character) => character.toUpperCase());
};

const getSeed = (path: string) =>
  `emailcn-${path
    .replace(/\.[^.]+$/, "")
    .replaceAll(/[^a-z0-9]+/gi, "-")
    .replaceAll(/^-|-$/g, "")
    .toLowerCase()}`;

export const emailAsset = (path: string) => {
  const normalizedPath = path.replace(/^\/+/, "");

  if (
    normalizedPath === "bento-grids/trend.png" ||
    normalizedPath === "bento-grids/trend-sm.png"
  ) {
    return `${ASSET_ORIGIN}/email-assets/${normalizedPath}`;
  }

  const seed = getSeed(normalizedPath);
  const hash = hashString(seed);
  const [background, foreground] =
    palettes[hash % palettes.length] ?? palettes[0];
  const [width, height] = getDimensions(normalizedPath);

  if (/(?:avatar|user|headshot|member|team)/i.test(normalizedPath)) {
    return `https://api.dicebear.com/9.x/lorelei/png?seed=${encodeURIComponent(
      seed
    )}&size=${Math.max(width, height)}&backgroundColor=${background.toLowerCase()}`;
  }

  if (/(?:trend|chart)/i.test(normalizedPath)) {
    return `${ASSET_ORIGIN}/email-assets/bento-grids/trend.png`;
  }

  if (
    /(?:icon|btc|eth|logo|insignia|badge-app|badge-google)/i.test(
      normalizedPath
    )
  ) {
    return `https://placehold.co/${width}x${height}/${background}/${foreground}.png?text=${encodeURIComponent(
      getLabel(normalizedPath)
    )}`;
  }

  return `https://picsum.photos/seed/${encodeURIComponent(
    seed
  )}/${width}/${height}.jpg`;
};
